CREATE TABLE IF NOT EXISTS public.analysis_self_learning (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  analysis_id uuid NOT NULL,
  user_id uuid,
  global_status text NOT NULL DEFAULT 'unknown', -- INFERRED default value, verify
  numeric_consistency numeric,
  rvce_agreement numeric,
  benchmark_alignment numeric,
  pl36_coherence numeric,
  mc_stability numeric,
  issues jsonb NOT NULL DEFAULT '{}'::jsonb,
  adjustments jsonb NOT NULL DEFAULT '{}'::jsonb,
  learning_config_version integer,
  evaluated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.analysis_self_learning ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Deny anon access" ON public.analysis_self_learning
  AS RESTRICTIVE FOR ALL TO anon USING (false) WITH CHECK (false);

